/********************************************************************
// Detect Mouse wheel scroll
********************************************************************/ // Get the specific section by its ID
const sectionScene = document.getElementById("container-opening-scene");
// Get all sections
const sections = document.querySelectorAll("section");
let isScrolling = false;
// Function to scroll to a specific section
function scrollToSection(index) {
    isScrolling = true;
    if (index >= 0 && index < sections.length) lenisSite.scrollTo(sections[index], {
        duration: 1.0,
        offset: 0,
        lock: true,
        onComplete: ()=>{
            isScrolling = false;
        }
    });
}
// Mouse wheel event listener
window.addEventListener("wheel", (event)=>{
    if (isScrolling) return; // Prevent multiple scrolls while one is in progress
    // scrolling down
    if (event.deltaY > 0 && !overlayIsOpen) {
        isScrolling = true;
        currentSectionIndex = Math.min(currentSectionIndex + 1, sections.length - 1);
        lines[currentSectionIndex - 1].classList.add("highlight-down");
        scrollToSection(currentSectionIndex);
        activeIndex = currentSectionIndex;
        navItems[currentSectionIndex].classList.add("active");
        navItems[currentSectionIndex - 1].classList.remove("active");
        setTimeout(()=>{
            lines[currentSectionIndex - 1].classList.remove("highlight-up", "highlight-down");
        }, 600);
        if (controls !== undefined) controls.unlock();
    } else if (event.deltaY < 0 && !overlayIsOpen) {
        // Scrolling up, move to previous section
        isScrolling = true;
        currentSectionIndex = Math.max(currentSectionIndex - 1, 0);
        lines[currentSectionIndex].classList.add("highlight-up");
        scrollToSection(currentSectionIndex);
        activeIndex = currentSectionIndex;
        navItems[currentSectionIndex].classList.add("active");
        navItems[currentSectionIndex + 1].classList.remove("active");
        setTimeout(()=>{
            lines[currentSectionIndex].classList.remove("highlight-up", "highlight-down");
        }, 600);
    }
});
/********************************************************************
// Handle Overlay
********************************************************************/ const imageContainers = document.querySelectorAll(".image-container");
const closeBtn = document.getElementById("closeBtn");
let overlayTouchStart = 0;
imageContainers.forEach((container)=>{
    container.addEventListener("click", ()=>{
        isScrolling = false;
        overlay.classList.add("show");
        lenisSite.stop();
        closeBtn.classList.add("show");
        overlayIsOpen = !overlayIsOpen;
        nav.classList.add("hide");
    });
});
function fnHandleCloseOverlay() {
    isScrolling = false;
    overlayIsOpen = !overlayIsOpen;
    overlay.classList.remove("show");
    closeBtn.classList.remove("show");
    setTimeout(()=>{
        lenisOverlay.scrollTo(0);
    }, 1000);
    if (!visitedFromMobileDevice) nav.classList.remove("hide");
    lenisSite.start();
}
closeBtn.addEventListener("click", ()=>{
    fnHandleCloseOverlay();
});
// Optional: Hide overlay when clicking outside of it
overlay.addEventListener("click", (e)=>{
    e.stopPropagation();
    fnHandleCloseOverlay();
});
overlay.addEventListener("touchstart", function(event) {
    overlayTouchStart = event.touches[0].clientX; // Get the initial x position of the touch
});
overlay.addEventListener("touchmove", (e)=>{
    const currentX = e.touches[0].clientX; // Get the current x position of the touch
    const deltaX = currentX - overlayTouchStart; // Calculate the difference
    //swiping right
    if (deltaX > 40) {
        overlay.classList.remove("show");
        closeBtn.classList.remove("show");
        lenisSite.start();
        setTimeout(()=>{
            lenisOverlay.scrollTo(0);
        }, 1000);
    }
});
