            if (U._lens[clr][wrd] != null) {
                var dl = U._lens[clr][wrd];
                wrd = "";
                len += dl;
                if (dl < 64) {
                    U._addNtimes(line, len, clr);
                    clr = 1 - clr;
                    len = 0;
                }
            }
